const fn = new Function(code + "\nreturn { stats };");
const { stats } = fn();
const s = stats(3, 1, 4, 1, 5);
if (s.min !== 1 || s.max !== 5) throw new Error("stats(3, 1, 4, 1, 5) should report min 1 and max 5.");

const fn = new Function(code + "\nreturn { stats };");
const { stats } = fn();
if (Math.abs(stats(2, 4, 6).avg - 4) > 1e-9) throw new Error("stats(2, 4, 6).avg should be 4.");
if (Math.abs(stats(1, 2).avg - 1.5) > 1e-9) throw new Error("stats(1, 2).avg should be 1.5.");

const fn = new Function(code + "\nreturn { stats };");
const { stats } = fn();
const s = stats();
if (s.min !== 0 || s.max !== 0 || s.avg !== 0) throw new Error("stats() with no arguments must return { min: 0, max: 0, avg: 0 }.");
